"""Solidity error ABI 解析、selector 与 revert data 编解码。

- :func:`parse_error_abi`：解析 ABI JSON 字符串或等价条目数组，只消费
  ``type == "error"`` 的条目，按声明顺序返回不可变
  :class:`ErrorDefinition`；function / event / constructor / receive /
  fallback 条目跳过不解析。
- :func:`canonical_error_signature`：返回 ``Name(type1,type2,...)`` 形式
  的规范错误签名（参数名不参与）。
- :func:`error_selector`：返回 ``keccak256(规范签名)[:4]`` 的四字节
  selector（bytes）。
- :func:`encode_error_data`：按错误名（无重载时）或规范签名选择 error，
  按 inputs 声明顺序把 list/tuple 实参编码为 ``selector + ABI(参数
  tuple)`` 的完整 revert data，返回 :class:`EncodedErrorData`。
- :func:`decode_error_data`：按 revert data 前四字节 selector 定位
  error，再严格解码参数 tuple，返回 :class:`DecodedErrorData`，携带
  名称、规范类型与值 tuple；无参数 error 的 revert data 即四字节
  selector，解码为空 tuple。

错误约定：

- 元数据非法（ABI 根不是数组、error 条目缺 name/type/inputs、标识符
  非法、参数类型字符串无法解析、规范签名重复等）抛
  :class:`abi_kit.AbiMetadataError`；
- 错误名或规范签名无匹配抛 :class:`abi_kit.AbiErrorNotFoundError`；
- 只给错误名但同名重载不止一个、无法唯一选择抛
  :class:`abi_kit.AbiErrorOverloadError`；
- revert data 少于四字节抛 :class:`abi_kit.AbiErrorDataLengthError`；
- selector 匹配不到任何 error 抛 :class:`abi_kit.AbiErrorSelectorError`；
- 实参不能按声明类型编码、或参数区不能按声明类型严格解码抛
  :class:`abi_kit.ABIValueError`；
- 参数消费完后仍有尾随字节抛 :class:`abi_kit.AbiErrorTrailingDataError`；
- revert data 不是 bytes 或可选 ``0x`` 前缀的偶数位十六进制字符串抛
  :class:`abi_kit.ABIValueError`。
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field

from ._codec import _decode, _encode
from ._event import _build_type, _is_identifier
from ._exceptions import (
    AbiErrorDataLengthError,
    AbiErrorNotFoundError,
    AbiErrorOverloadError,
    AbiErrorSelectorError,
    AbiErrorTrailingDataError,
    AbiEventError,
    AbiMetadataError,
    ABITypeError,
    ABIValueError,
)
from ._format import format_abi_type
from ._keccak import keccak_256
from ._types import ABIType, TupleType

_SELECTOR_LEN = 4
_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")

#: error 路径跳过但允许保留在 ABI 中的非 error 条目类型；这些条目的合法性
#: 由各自入口（如函数、事件路径）负责，本模块不解析。
_NON_ERROR_ENTRY_TYPES = frozenset(
    ("function", "event", "constructor", "receive", "fallback")
)


# ---- 不可变定义与结果对象 -------------------------------------------------


@dataclass(frozen=True)
class ErrorArgument:
    """error 的单个参数（声明顺序保留）。

    - ``name``：ABI JSON 中的参数名，缺省为空串；
    - ``abi_type``：由 ``type`` + ``components`` 展开得到的类型对象；
    - ``value``：解码结果中按值层口径还原的 Python 值；定义中为 None。
    """

    name: str
    abi_type: ABIType
    value: object = None

    @property
    def type(self) -> str:
        """规范 ABI 类型字符串（不含空白与参数名）。"""
        return format_abi_type(self.abi_type)


@dataclass(frozen=True)
class ErrorDefinition:
    """不可变 error 定义。

    - ``name``：非空 ASCII 错误标识符；
    - ``inputs``：按声明顺序保存的 :class:`ErrorArgument`。
    """

    name: str
    inputs: tuple[ErrorArgument, ...] = field(default=())


@dataclass(frozen=True)
class EncodedErrorData:
    """error revert data 编码结果。

    - ``error``：命中的 :class:`ErrorDefinition`；
    - ``selector``：四字节 selector（bytes）；
    - ``data``：``selector + 参数 ABI 编码`` 的完整 revert data。
    """

    error: ErrorDefinition
    selector: bytes
    data: bytes

    @property
    def error_name(self) -> str:
        """命中 error 的名称。"""
        return self.error.name

    @property
    def signature(self) -> str:
        """命中 error 的规范签名，如 ``InsufficientBalance(address,uint256)``。"""
        return canonical_error_signature(self.error)

    @property
    def selector_hex(self) -> str:
        """``"0x"`` + 8 个小写十六进制字符形式的 selector。"""
        return "0x" + self.selector.hex()

    @property
    def data_hex(self) -> str:
        """``"0x"`` 前缀的完整 revert data 十六进制字符串。"""
        return "0x" + self.data.hex()


@dataclass(frozen=True)
class DecodedErrorData:
    """error revert data 解码结果。

    - ``error``：selector 命中的 :class:`ErrorDefinition`；
    - ``selector``：revert data 前四字节（bytes）；
    - ``args``：按声明顺序排列的 :class:`ErrorArgument`，``value`` 为
      还原值。
    """

    error: ErrorDefinition
    selector: bytes
    args: tuple[ErrorArgument, ...] = field(default=())

    @property
    def error_name(self) -> str:
        """命中 error 的名称。"""
        return self.error.name

    @property
    def signature(self) -> str:
        """命中 error 的规范签名，如 ``InsufficientBalance(address,uint256)``。"""
        return canonical_error_signature(self.error)

    @property
    def selector_hex(self) -> str:
        """``"0x"`` + 8 个小写十六进制字符形式的 selector。"""
        return "0x" + self.selector.hex()

    @property
    def types(self) -> tuple[str, ...]:
        """按声明顺序排列的规范 ABI 类型字符串 tuple。"""
        return tuple(arg.type for arg in self.args)

    @property
    def values(self) -> tuple:
        """按声明顺序去掉类型标注后的纯值 tuple。"""
        return tuple(arg.value for arg in self.args)


# ---- ABI 解析 -------------------------------------------------------------


def _metadata(message: str) -> AbiMetadataError:
    return AbiMetadataError(message)


def _parse_error_entry(entry: dict) -> ErrorDefinition:
    """从单个 ABI error 条目构造不可变错误定义。"""
    name = entry.get("name")
    if not _is_identifier(name):
        raise _metadata(f"error name 必须是非空 ASCII 标识符，得到 {name!r}")
    if "inputs" not in entry:
        raise _metadata(f"error {name!r} 缺少 inputs")
    inputs_node = entry["inputs"]
    if not isinstance(inputs_node, (list, tuple)):
        raise _metadata(f"error {name!r} 的 inputs 必须是数组")

    parameters: list[ErrorArgument] = []
    for node in inputs_node:
        if not isinstance(node, dict):
            raise _metadata(
                f"error {name!r} 的参数必须是 JSON 对象，"
                f"得到 {type(node).__name__}"
            )
        param_name = node.get("name", "")
        if not isinstance(param_name, str):
            raise _metadata(
                f"error {name!r} 的参数 name 必须是字符串，得到 {param_name!r}"
            )
        try:
            # 与事件、函数路径共用同一套 type + components 递归展开；其
            # 失败统一是事件层错误码，这里转译为 error 元数据错误。
            abi_type = _build_type(node)
        except (AbiEventError, ABITypeError) as exc:
            raise _metadata(f"error {name!r} 的参数类型非法：{exc}") from None
        parameters.append(ErrorArgument(param_name, abi_type))
    return ErrorDefinition(name, tuple(parameters))


def parse_error_abi(abi) -> tuple[ErrorDefinition, ...]:
    """解析 ABI，返回其中全部 error 条目的不可变定义。

    ``abi`` 接受 ABI JSON 字符串（:func:`json.loads` 口径）或等价的
    Python 条目数组（list/tuple）。只消费 ``type == "error"`` 的条目，
    按声明顺序返回；function、event、constructor、receive、fallback 等
    其他条目原样保留在 ABI 中但不解析、不影响 error 路径。error 条目的
    ``inputs`` 必填；签名只由 name 与 inputs 的规范类型构成，参数名不
    参与。任何 error 元数据非法（含规范签名重复）抛
    :class:`abi_kit.AbiMetadataError`。
    """
    if isinstance(abi, str):
        try:
            root = json.loads(abi)
        except (json.JSONDecodeError, ValueError) as exc:
            raise _metadata(f"ABI JSON 解析失败：{exc}") from None
    elif isinstance(abi, (list, tuple)):
        root = abi
    else:
        raise _metadata(
            f"ABI 必须是 JSON 字符串或条目数组，得到 {type(abi).__name__}"
        )

    if not isinstance(root, (list, tuple)):
        raise _metadata("ABI 必须是条目数组，JSON 根不能是对象或标量")

    errors: list[ErrorDefinition] = []
    for entry in root:
        if not isinstance(entry, dict):
            raise _metadata(
                f"ABI 条目必须是 JSON 对象，得到 {type(entry).__name__}"
            )
        entry_type = entry.get("type")
        # function/event/constructor/receive/fallback 条目保留在 ABI 中供
        # 各自入口使用，error 路径跳过且不校验；缺 type 或未知条目类型属
        # 元数据非法，统一抛 AbiMetadataError。
        if entry_type == "error":
            errors.append(_parse_error_entry(entry))
        elif entry_type in _NON_ERROR_ENTRY_TYPES:
            continue
        else:
            raise _metadata(
                f"ABI 条目缺少 type 或带有未知类型 {entry_type!r}，"
                "合法值为 function/event/constructor/error/receive/fallback"
            )

    seen: set[str] = set()
    for error in errors:
        signature = canonical_error_signature(error)
        if signature in seen:
            raise _metadata(f"error 规范签名重复：{signature!r}")
        seen.add(signature)
    return tuple(errors)


# ---- 规范签名与 selector --------------------------------------------------


def canonical_error_signature(error: ErrorDefinition) -> str:
    """返回规范错误签名 ``Name(type1,type2,...)``。

    参数名不参与签名；tuple 输出为 ``(t1,t2)``，数组保留 ``[]``/``[n]``
    后缀。
    """
    if not isinstance(error, ErrorDefinition):
        raise _metadata(
            f"需要 ErrorDefinition，得到 {type(error).__name__}"
        )
    canonical = ",".join(format_abi_type(p.abi_type) for p in error.inputs)
    return f"{error.name}({canonical})"


def error_selector(error: ErrorDefinition) -> bytes:
    """返回 error 四字节 selector：``keccak256(规范签名)[:4]``。"""
    signature = canonical_error_signature(error)
    try:
        digest = keccak_256(signature.encode("utf-8"))
    except (TypeError, ValueError) as exc:
        raise _metadata(f"规范签名无法生成 selector：{exc}") from None
    return digest[:_SELECTOR_LEN]


# ---- 选择 error -----------------------------------------------------------


def _resolve_error(errors: tuple[ErrorDefinition, ...], key) -> ErrorDefinition:
    """按错误名或规范签名在已解析 error 中唯一定位。"""
    if not isinstance(key, str) or not key:
        raise _metadata(f"错误名或规范签名必须是非空字符串，得到 {key!r}")

    if "(" in key or ")" in key:
        for error in errors:
            if canonical_error_signature(error) == key:
                return error
        raise AbiErrorNotFoundError(
            f"ABI 中找不到规范签名为 {key!r} 的 error"
        )

    if not _is_identifier(key):
        raise _metadata(f"非法错误名：{key!r}")

    candidates = [error for error in errors if error.name == key]
    if not candidates:
        raise AbiErrorNotFoundError(f"ABI 中找不到 error {key!r}")
    if len(candidates) > 1:
        signatures = ", ".join(
            canonical_error_signature(error) for error in candidates
        )
        raise AbiErrorOverloadError(
            f"error {key!r} 存在 {len(candidates)} 个重载，无法唯一选择，"
            f"请改用规范签名之一：{signatures}"
        )
    return candidates[0]


# ---- revert data 编解码 ---------------------------------------------------


def _coerce_error_data(data) -> bytes:
    """把 bytes 或可选 0x 前缀的偶数位十六进制字符串规范化为 bytes。"""
    if isinstance(data, bytes):
        return data
    if isinstance(data, str):
        text = data[2:] if data[:2] in ("0x", "0X") else data
        if len(text) % 2 or any(c not in _HEX_DIGITS for c in text):
            raise ABIValueError(
                "revert data 必须是可选 0x 前缀的偶数位十六进制字符串"
            )
        return bytes.fromhex(text)
    raise ABIValueError(
        f"revert data 必须是 bytes 或十六进制 str，得到 {type(data).__name__}"
    )


def _input_types(error: ErrorDefinition) -> TupleType:
    return TupleType(tuple(parameter.abi_type for parameter in error.inputs))


def encode_error_data(abi, error_name, args=None) -> EncodedErrorData:
    """编码一次 error revert data。

    ``abi`` 接受 ABI JSON 字符串或等价条目数组；``error_name`` 接受
    错误名（ABI 中无同名重载时）或规范错误签名
    （``InsufficientBalance(address,uint256)``）；``args`` 为按 inputs
    声明顺序排列的实参列表（list/tuple），无参 error 可省略。

    返回 :class:`EncodedErrorData`，其中 ``selector`` 为四字节 bytes，
    ``data`` 为 ``selector + 参数 tuple 的 ABI 编码`` 的完整 revert
    data。实参不能按声明类型编码（含数量不符）抛
    :class:`abi_kit.ABIValueError`。
    """
    errors = parse_error_abi(abi)
    error = _resolve_error(errors, error_name)

    if args is None:
        values = ()
    elif isinstance(args, (list, tuple)):
        values = tuple(args)
    else:
        raise ABIValueError(
            f"实参列表必须是 list 或 tuple，得到 {type(args).__name__}"
        )

    payload = _encode(_input_types(error), values)
    selector = error_selector(error)
    return EncodedErrorData(error, selector, selector + payload)


def decode_error_data(abi, data) -> DecodedErrorData:
    """解码完整 error revert data。

    ``data`` 接受 bytes 或可选 ``0x`` 前缀的偶数位十六进制字符串，前四
    字节必须是 ABI 中某个 error 的 selector；其后按该 error inputs 组成
    的 tuple 严格 ABI 解码。返回 :class:`DecodedErrorData`，携带 error
    定义、selector、规范签名（属性）与按声明顺序排列的带类型标注参数；
    ``values`` 属性给出等价的纯值 tuple。无参数 error 的 revert data 即
    四字节 selector，解码为空 tuple。

    data 类型或十六进制非法抛 :class:`abi_kit.ABIValueError`；少于四字节
    抛 :class:`abi_kit.AbiErrorDataLengthError`；selector 无匹配抛
    :class:`abi_kit.AbiErrorSelectorError`；参数区不能严格解码抛
    :class:`abi_kit.ABIValueError`；解码后仍有尾随字节抛
    :class:`abi_kit.AbiErrorTrailingDataError`。
    """
    errors = parse_error_abi(abi)
    raw = _coerce_error_data(data)

    if len(raw) < _SELECTOR_LEN:
        raise AbiErrorDataLengthError(
            f"revert data 长度必须至少为 {_SELECTOR_LEN} 字节以容纳 "
            f"selector，得到 {len(raw)} 字节"
        )
    selector = raw[:_SELECTOR_LEN]

    matches = [error for error in errors if error_selector(error) == selector]
    if not matches:
        raise AbiErrorSelectorError(
            f"selector 0x{selector.hex()} 在 ABI 中匹配不到任何 error"
        )
    error = matches[0]

    payload = raw[_SELECTOR_LEN:]
    bound = len(payload)
    values, end = _decode(_input_types(error), payload, 0, bound)
    if end != bound:
        raise AbiErrorTrailingDataError(
            f"参数解码完成后仍有 {bound - end} 字节尾随数据未被消费"
        )

    arguments = tuple(
        ErrorArgument(parameter.name, parameter.abi_type, value)
        for parameter, value in zip(error.inputs, values)
    )
    return DecodedErrorData(error, selector, arguments)

"""事件 ABI 解析、签名 topic0 与日志还原。

- :func:`parse_event_abi`：解析 ABI JSON 的 event 对象，返回不可变的
  :class:`EventDefinition`，保留声明顺序与名称、indexed、anonymous 等
  声明元数据；tuple 参数由 ``components`` 递归展开。
- :func:`event_topic0`：按事件名与参数的规范 ABI 类型计算
  ``keccak256("Name(type1,type2,...)")``，返回小写 ``"0x"`` + 64 位
  十六进制；参数名与 indexed 不参与签名，anonymous 事件返回 None。
- :func:`decode_event_log`：校验 topics 并严格还原 data，按声明顺序
  合并为一个 tuple。
- :func:`encode_event_log`：按声明值生成日志 topics 与 data，返回不可变
  :class:`EncodedEventLog`，与 :func:`decode_event_log` 的 topics 数量、
  补零方向与 data tuple 口径一致。

日志口径：

- 非 indexed 参数由 data 按 tuple 严格 ABI 解码，值口径与
  :func:`decode_abi_value` 完全一致；没有非 indexed 参数时 data 必须
  为空。
- indexed 的 address/bool/intM/uintM/bytesM 从各自 32 字节 topic 严格
  解码；indexed 的 string、动态 bytes、数组与 tuple 不可逆，原样返回
  32 字节 topic，口径为 bytes。

编码口径（encode_event_log）：

- 非 indexed 参数组成 tuple，按 :func:`encode_abi_value` 的 ABI 值编码
  生成 data；没有非 indexed 参数时 data 为空字节串。
- 非匿名事件 topics 首项为签名 topic0 的 32 字节，匿名事件不放；其后按
  声明顺序放置 indexed 主题，topics 总数与解码口径一致。
- indexed 的 address/bool/intM/uintM/bytesM 直接生成 32 字节 ABI 规范
  字（address 左补零、bytesM 右补零，与解码补零方向一致）；indexed 的
  string、动态 bytes、数组与 tuple 取事件索引特殊编码的 Keccak-256
  主题——string 用 UTF-8 字节、动态 bytes 用内容、数组省略长度递归连接
  元素、tuple 递归连接成员；基础值用 32 字节规范字（bytesM 右补零），
  递归成员与整段结果右补齐到 32 字节倍数，string 与动态 bytes 内容不
  补零。

所有失败统一抛出 :class:`abi_kit.AbiEventError`，以 ``code`` 区分。
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field

from ._codec import _encode, decode_abi_value
from ._exceptions import ABITypeError, ABIValueError, AbiEventError
from ._format import format_abi_type
from ._keccak import keccak_256
from ._parser import parse_abi_type
from ._types import ABIType, ArrayType, ElementaryType, TupleType

_WORD = 32
_HEX_DIGITS = set("0123456789abcdefABCDEF")
_SUFFIX_RE = re.compile(r"^(\[\d*\])*$")
_SUFFIX_PART = re.compile(r"\[(\d*)\]")

#: components 递归展开的安全上限，与类型解析器一致：语义嵌套上限
#: （128 层）由类型对象构造时检查；此阈值仅用于在触及 Python 递归限制
#: 前抛出 EVENT_ABI_INVALID。
_RECURSION_SAFETY_LIMIT = 200


@dataclass(frozen=True)
class EventParameter:
    """事件的单个参数（声明顺序保留）。

    - ``name``：ABI JSON 中的参数名，缺省为空串；
    - ``abi_type``：由 ``type`` + ``components`` 展开得到的类型对象；
    - ``indexed``：是否进入 topics。
    """

    name: str
    abi_type: ABIType
    indexed: bool = False


@dataclass(frozen=True)
class EventDefinition:
    """不可变事件定义。

    - ``name``：非空 ASCII 事件标识符；
    - ``inputs``：按声明顺序保存的 :class:`EventParameter`；
    - ``anonymous``：是否为匿名事件（缺省视为 False）。
    """

    name: str
    inputs: tuple[EventParameter, ...] = field(default=())
    anonymous: bool = False


@dataclass(frozen=True)
class EncodedEventLog:
    """不可变事件日志编码结果。

    - ``event``：对应的 :class:`EventDefinition`；
    - ``topics``：bytes tuple——非匿名事件首项为签名 topic0 的 32 字节，
      其后按声明顺序排列 indexed 主题；
    - ``data``：非 indexed 参数 tuple 的 ABI 值编码，无非 indexed 参数
      时为空字节串；
    - ``topics_hex`` / ``data_hex``：对应的 ``"0x"`` 小写十六进制形式。
    """

    event: EventDefinition
    topics: tuple[bytes, ...] = field(default=())
    data: bytes = b""

    @property
    def topics_hex(self) -> tuple[str, ...]:
        """各项 topics 的 ``"0x"`` + 64 位小写十六进制 tuple。"""
        return tuple("0x" + topic.hex() for topic in self.topics)

    @property
    def data_hex(self) -> str:
        """``data`` 的 ``"0x"`` 前缀小写十六进制字符串。"""
        return "0x" + self.data.hex()


# ---- ABI JSON 解析 -------------------------------------------------------


def _invalid(message: str) -> AbiEventError:
    return AbiEventError("EVENT_ABI_INVALID", message)


def _is_identifier(name) -> bool:
    if not isinstance(name, str) or not name or not name.isascii():
        return False
    first, rest = name[0], name[1:]
    if not (first.isalpha() or first in "_$"):
        return False
    return all(ch.isalnum() or ch in "_$" for ch in rest)


def _apply_suffixes(inner: ABIType, suffix: str) -> ABIType:
    """把 ``"[]"`` / ``"[n]"`` 后缀序列依次套到 inner 外层。"""
    current = inner
    for match in _SUFFIX_PART.finditer(suffix):
        digits = match.group(1)
        if digits:
            # 与类型解析器一致：拒绝 0 长度与前导零。
            if digits[0] == "0":
                raise _invalid(f"数组长度必须是无前导零的正整数：[{digits}]")
            current = ArrayType(current, int(digits))
        else:
            current = ArrayType(current)
    return current


def _build_type(node, depth: int = 1) -> ABIType:
    """从一个 ABI 参数 JSON 节点递归构造类型对象。"""
    if depth > _RECURSION_SAFETY_LIMIT:
        raise _invalid("components 嵌套过深")
    if not isinstance(node, dict):
        raise _invalid(f"参数描述必须是 JSON 对象，得到 {type(node).__name__}")
    type_string = node.get("type")
    if not isinstance(type_string, str) or not type_string:
        raise _invalid(f"参数必须带有非空字符串 type，得到 {type_string!r}")

    if type_string == "tuple" or type_string.startswith("tuple["):
        suffix = type_string[len("tuple"):]
        if not _SUFFIX_RE.match(suffix):
            raise _invalid(f"非法 tuple 类型字符串：{type_string!r}")
        components_node = node.get("components")
        if not isinstance(components_node, list):
            raise _invalid(
                f"tuple 参数必须带有列表形式的 components：{type_string!r}"
            )
        component_types: list[ABIType] = []
        component_names: list[str | None] = []
        for component in components_node:
            component_types.append(_build_type(component, depth + 1))
            if isinstance(component, dict) and isinstance(component.get("name"), str):
                component_names.append(component["name"] or None)
            else:
                component_names.append(None)
        try:
            current: ABIType = TupleType(
                tuple(component_types), names=tuple(component_names)
            )
            if suffix:
                current = _apply_suffixes(current, suffix)
        except ABITypeError as exc:
            raise _invalid(f"tuple 类型构造失败：{exc}") from None
        return current

    if "components" in node:
        raise _invalid(f"非 tuple 参数不能带有 components：{type_string!r}")
    try:
        return parse_abi_type(type_string)
    except ABITypeError as exc:
        raise _invalid(f"参数类型 {type_string!r} 非法：{exc}") from None


def _build_inputs(event_json: dict) -> tuple[EventParameter, ...]:
    inputs_node = event_json.get("inputs", [])
    if not isinstance(inputs_node, list):
        raise _invalid("事件 inputs 必须是数组")
    inputs: list[EventParameter] = []
    for node in inputs_node:
        if not isinstance(node, dict):
            raise _invalid(f"事件参数必须是 JSON 对象，得到 {type(node).__name__}")
        name = node.get("name", "")
        if not isinstance(name, str):
            raise _invalid(f"事件参数 name 必须是字符串，得到 {name!r}")
        indexed = node.get("indexed", False)
        if not isinstance(indexed, bool):
            raise _invalid(f"indexed 必须是布尔值，得到 {indexed!r}")
        inputs.append(EventParameter(name, _build_type(node), indexed))
    return tuple(inputs)


def parse_event_abi(event_json: dict) -> EventDefinition:
    """解析 ABI JSON 的 event 对象，返回不可变 :class:`EventDefinition`。

    要求 ``type == "event"``、``name`` 为非空 ASCII 标识符；布尔标志
    缺失视为 False；tuple 参数由 ``components`` 递归展开。任何非法输入
    抛出带 ``EVENT_ABI_INVALID`` 的 :class:`abi_kit.AbiEventError`。
    """
    if not isinstance(event_json, dict):
        raise _invalid(
            f"事件描述必须是 JSON 对象，得到 {type(event_json).__name__}"
        )
    if event_json.get("type") != "event":
        raise _invalid(f"type 必须为 \"event\"，得到 {event_json.get('type')!r}")
    name = event_json.get("name")
    if not _is_identifier(name):
        raise _invalid(f"事件 name 必须是非空 ASCII 标识符，得到 {name!r}")
    anonymous = event_json.get("anonymous", False)
    if not isinstance(anonymous, bool):
        raise _invalid(f"anonymous 必须是布尔值，得到 {anonymous!r}")
    return EventDefinition(name, _build_inputs(event_json), anonymous)


# ---- topic0 --------------------------------------------------------------


def _event_signature(event: EventDefinition) -> str:
    canonical = ",".join(format_abi_type(param.abi_type) for param in event.inputs)
    return f"{event.name}({canonical})"


def event_topic0(event: EventDefinition) -> str | None:
    """计算事件签名 topic0。

    返回小写 ``"0x"`` + 64 位十六进制；anonymous 事件返回 None。
    参数名与 indexed 不参与签名。
    """
    if not isinstance(event, EventDefinition):
        raise _invalid(
            f"需要 EventDefinition，得到 {type(event).__name__}"
        )
    if event.anonymous:
        return None
    digest = keccak_256(_event_signature(event).encode("utf-8"))
    return "0x" + digest.hex()


# ---- 日志还原 ------------------------------------------------------------


def _error(code: str, message: str) -> AbiEventError:
    return AbiEventError(code, message)


def _topic_bytes(item) -> bytes:
    """把单个 topic 规范化为 32 字节，失败抛 EVENT_TOPIC_VALUE。"""
    if isinstance(item, bytes):
        if len(item) != _WORD:
            raise _error(
                "EVENT_TOPIC_VALUE",
                f"topic 必须是 32 字节，得到 {len(item)} 字节",
            )
        return item
    if isinstance(item, str):
        text = item[2:] if item.startswith(("0x", "0X")) else item
        if len(text) != 64 or any(c not in _HEX_DIGITS for c in text):
            raise _error(
                "EVENT_TOPIC_VALUE",
                "topic 必须是可选 0x 前缀的 64 位十六进制字符串",
            )
        return bytes.fromhex(text)
    raise _error(
        "EVENT_TOPIC_VALUE",
        f"topic 必须是 bytes 或十六进制字符串，得到 {type(item).__name__}",
    )


def _data_bytes(data) -> bytes:
    """把 data 规范化为字节串，失败抛 EVENT_DATA_INVALID。"""
    if isinstance(data, bytes):
        return data
    if isinstance(data, str):
        text = data[2:] if data.startswith(("0x", "0X")) else data
        if len(text) % 2 or any(c not in _HEX_DIGITS for c in text):
            raise _error(
                "EVENT_DATA_INVALID",
                "data 必须是可选 0x 前缀的偶数位十六进制字符串",
            )
        return bytes.fromhex(text)
    raise _error(
        "EVENT_DATA_INVALID",
        f"data 必须是 bytes 或十六进制字符串，得到 {type(data).__name__}",
    )


def _decode_indexed(abi_type: ABIType, topic: bytes):
    """从 32 字节 topic 严格解码可还原的 indexed 基础值。"""
    if isinstance(abi_type, ArrayType) or isinstance(abi_type, TupleType):
        return topic
    if not isinstance(abi_type, ElementaryType):
        return topic
    kind = abi_type.kind
    if kind == "string" or (kind == "bytes" and abi_type.byte_size is None):
        return topic
    if kind == "address":
        if topic[:12] != b"\x00" * 12:
            raise _error("EVENT_TOPIC_VALUE", "address topic 高位 12 字节非零")
        return "0x" + topic[12:].hex()
    if kind == "bool":
        if topic == b"\x00" * _WORD:
            return False
        if topic == b"\x00" * (_WORD - 1) + b"\x01":
            return True
        raise _error("EVENT_TOPIC_VALUE", "bool topic 既非全 0 也非末尾字节为 1")
    if kind == "uint":
        value = int.from_bytes(topic, "big", signed=False)
        if value >= 1 << abi_type.bit_size:
            raise _error(
                "EVENT_TOPIC_VALUE",
                f"uint{abi_type.bit_size} topic 解码值越界：{value}",
            )
        return value
    if kind == "int":
        value = int.from_bytes(topic, "big", signed=True)
        bits = abi_type.bit_size
        low = -(1 << (bits - 1))
        high = (1 << (bits - 1)) - 1
        if not low <= value <= high:
            raise _error(
                "EVENT_TOPIC_VALUE",
                f"int{bits} topic 解码值超出补码范围：{value}",
            )
        return value
    # bytesM
    if topic[abi_type.byte_size:] != b"\x00" * (_WORD - abi_type.byte_size):
        raise _error(
            "EVENT_TOPIC_VALUE",
            f"bytes{abi_type.byte_size} topic 尾部填充非零",
        )
    return topic[:abi_type.byte_size]


def decode_event_log(event: EventDefinition, topics, data) -> tuple:
    """校验日志并还原事件参数。

    非匿名事件的 topics 必须以正确 topic0 开头，总数为 indexed 参数数
    加一；匿名事件总数等于 indexed 参数数。data 必须能按非 indexed
    参数组成的 tuple 严格解码，无此类参数时必须为空。返回值按参数声明
    顺序合并为一个 tuple。任何失败抛 :class:`abi_kit.AbiEventError`。
    """
    if not isinstance(event, EventDefinition):
        raise _invalid(f"需要 EventDefinition，得到 {type(event).__name__}")
    if isinstance(topics, (str, bytes)) or not isinstance(topics, (list, tuple)):
        raise _error(
            "EVENT_TOPIC_VALUE",
            f"topics 必须是列表或元组，得到 {type(topics).__name__}",
        )

    indexed_params = [param for param in event.inputs if param.indexed]
    indexed_count = len(indexed_params)
    expected = indexed_count if event.anonymous else indexed_count + 1
    if len(topics) != expected:
        raise _error(
            "EVENT_TOPIC_COUNT",
            f"topics 数量应为 {expected}，得到 {len(topics)}",
        )

    normalized_topics = [_topic_bytes(item) for item in topics]
    if not event.anonymous:
        expected_topic0 = bytes.fromhex(event_topic0(event)[2:])
        if normalized_topics[0] != expected_topic0:
            raise _error(
                "EVENT_TOPIC0_MISMATCH",
                "topics[0] 与事件签名 topic0 不一致",
            )

    payload = _data_bytes(data)
    non_indexed = [param for param in event.inputs if not param.indexed]
    if non_indexed:
        data_type = TupleType(tuple(param.abi_type for param in non_indexed))
        try:
            decoded_data = decode_abi_value(data_type, payload)
        except ValueError as exc:
            # decode_abi_value 对严格布局的任何违反都抛 ValueError；
            # 统一为日志层错误码 EVENT_DATA_INVALID。
            raise _error("EVENT_DATA_INVALID", f"非 indexed 参数解码失败：{exc}") from None
    else:
        if payload:
            raise _error(
                "EVENT_DATA_INVALID",
                f"事件无非 indexed 参数，但 data 含有 {len(payload)} 字节",
            )
        decoded_data = ()

    result = []
    indexed_iter = iter(normalized_topics if event.anonymous else normalized_topics[1:])
    data_iter = iter(decoded_data)
    for param in event.inputs:
        if param.indexed:
            result.append(_decode_indexed(param.abi_type, next(indexed_iter)))
        else:
            result.append(next(data_iter))
    return tuple(result)


# ---- 日志编码 ------------------------------------------------------------


def _value_invalid(message: str) -> AbiEventError:
    return AbiEventError("EVENT_VALUE_INVALID", message)


def _word_pad(payload: bytes) -> bytes:
    """把内容右补齐到 32 字节倍数（已对齐时原样返回）。"""
    return payload + b"\x00" * (-len(payload) % _WORD)


def _indexed_preimage(abi_type: ABIType, value) -> bytes:
    """构造动态 indexed 值的事件索引特殊编码原像（尚未 Keccak）。

    - string：UTF-8 字节，不补零；动态 bytes：原始内容，不补零；
    - 其余基础类型：32 字节 ABI 规范字（bytesM 右补零）；
    - 数组：省略长度字，递归连接各元素，每个元素各自右补齐到 32 字节
      倍数；
    - tuple：递归连接各成员，每个成员各自右补齐到 32 字节倍数。

    值口径与 :func:`encode_abi_value` 完全一致，任何不匹配抛
    :class:`abi_kit.ABIValueError`。
    """
    if isinstance(abi_type, ElementaryType):
        kind = abi_type.kind
        if kind == "string":
            if not isinstance(value, str):
                raise ABIValueError(
                    f"string 需要 str，得到 {type(value).__name__}"
                )
            try:
                return value.encode("utf-8")
            except UnicodeEncodeError as exc:
                raise ABIValueError(f"字符串无法编码为 UTF-8：{exc}") from exc
        if kind == "bytes" and abi_type.byte_size is None:
            if not isinstance(value, bytes):
                raise ABIValueError(
                    f"bytes 需要 bytes，得到 {type(value).__name__}"
                )
            return value
        # 静态基础类型（address/bool/intM/uintM/bytesM）的规范字。
        return _encode(abi_type, value)
    if isinstance(abi_type, ArrayType):
        if not isinstance(value, list):
            raise ABIValueError(f"数组需要 list，得到 {type(value).__name__}")
        if abi_type.length is not None and len(value) != abi_type.length:
            raise ABIValueError(
                f"定长数组长度应为 {abi_type.length}，得到 {len(value)}"
            )
        # 省略数组长度字，递归连接元素；元素按 32 字节倍数右补齐。
        pieces = [
            _word_pad(_indexed_preimage(abi_type.element_type, item))
            for item in value
        ]
        return _word_pad(b"".join(pieces))
    if isinstance(abi_type, TupleType):
        if not isinstance(value, tuple):
            raise ABIValueError(f"元组需要 tuple，得到 {type(value).__name__}")
        if len(value) != len(abi_type.components):
            raise ABIValueError(
                f"元组长度应为 {len(abi_type.components)}，得到 {len(value)}"
            )
        # 递归连接成员；成员按 32 字节倍数右补齐。
        pieces = [
            _word_pad(_indexed_preimage(member_type, member_value))
            for member_type, member_value in zip(abi_type.components, value)
        ]
        return _word_pad(b"".join(pieces))
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


def _encode_indexed_topic(abi_type: ABIType, value) -> bytes:
    """把单个 indexed 值编码为 32 字节主题。"""
    if isinstance(abi_type, ElementaryType):
        kind = abi_type.kind
        is_dynamic_bytes = kind == "bytes" and abi_type.byte_size is None
        if kind != "string" and not is_dynamic_bytes:
            # address/bool/intM/uintM/bytesM 直接用 ABI 规范字，补零方向
            # 与 _decode_indexed 一致（address 左补零、bytesM 右补零）。
            return _encode(abi_type, value)
    # string、动态 bytes、数组（含定长数组）与 tuple 取 Keccak-256 主题。
    return keccak_256(_indexed_preimage(abi_type, value))


def encode_event_log(event: EventDefinition, values) -> EncodedEventLog:
    """按声明值编码事件日志，返回不可变 :class:`EncodedEventLog`。

    ``values`` 按参数声明顺序排列，接受 list 或 tuple，数量必须与事件
    参数数相等。非 indexed 参数组成 tuple 按 ABI 值编码生成 data，无非
    indexed 参数时 data 为 ``b""``；非匿名事件 topics 首项为签名
    topic0 的 32 字节，匿名事件不放，其后按声明顺序放置 indexed 主题，
    数量口径与 :func:`decode_event_log` 一致。

    indexed 的 address/bool/intM/uintM/bytesM 生成 32 字节 ABI 规范字；
    indexed 的 string、动态 bytes、数组与 tuple 生成事件索引特殊编码的
    Keccak-256 主题。相同输入始终得到相同结果。

    event 不是 :class:`EventDefinition`、values 不是 list/tuple、数量
    不符或任一值与其声明类型不匹配时，统一抛
    :class:`abi_kit.AbiEventError`（code 为 ``EVENT_VALUE_INVALID``）；
    :class:`abi_kit.ABIValueError` 与 :class:`abi_kit.ABITypeError` 不会
    泄漏到本入口之外。
    """
    if not isinstance(event, EventDefinition):
        raise _value_invalid(
            f"需要 EventDefinition，得到 {type(event).__name__}"
        )
    if not isinstance(values, (list, tuple)):
        raise _value_invalid(
            f"values 必须是 list 或 tuple，得到 {type(values).__name__}"
        )
    if len(values) != len(event.inputs):
        raise _value_invalid(
            f"values 数量应为 {len(event.inputs)}，得到 {len(values)}"
        )

    try:
        topics: list[bytes] = []
        if not event.anonymous:
            topics.append(bytes.fromhex(event_topic0(event)[2:]))

        indexed_topics: list[bytes] = []
        non_indexed_values: list = []
        for param, value in zip(event.inputs, values):
            if param.indexed:
                indexed_topics.append(_encode_indexed_topic(param.abi_type, value))
            else:
                non_indexed_values.append(value)
        topics.extend(indexed_topics)

        if non_indexed_values:
            data_type = TupleType(
                tuple(param.abi_type for param in event.inputs if not param.indexed)
            )
            data = _encode(data_type, tuple(non_indexed_values))
        else:
            data = b""
    except (ABIValueError, ABITypeError) as exc:
        raise _value_invalid(f"事件值编码失败：{exc}") from None

    return EncodedEventLog(event, tuple(topics), data)

"""合约级事件注册表与日志分派还原。

- :func:`parse_event_registry`：解析 ABI JSON 字符串或等价条目数组，只
  保留 ``type == "event"`` 的条目，按 ABI 声明顺序构建不可变
  :class:`EventRegistry`；其余条目跳过不解析。事件名、规范类型、
  indexed、anonymous 与 tuple components 语义与
  :func:`abi_kit.parse_event_abi` 完全一致。
- :func:`decode_contract_event_log`：分派并还原单条日志，返回
  ``(EventDefinition, topics, data, values)`` 四元组——命中的事件定义、
  规范化的 32 字节 topics tuple、data bytes 与按声明顺序排列的 values
  tuple。
- :func:`decode_contract_event_logs`：按输入顺序批量还原日志序列，返回
  等长 tuple；任一日志失败即整体抛出，不返回部分结果。

日志口径：

- 日志是映射（Mapping），``topics`` 与 ``data`` 必填，``event`` 可选；
  其余键忽略。
- ``topics`` 每项接受 32 字节 ``bytes`` 或可选 ``0x`` 前缀的 64 位
  十六进制字符串；``data`` 接受 ``bytes`` 或可选 ``0x`` 前缀的偶数位
  十六进制字符串——与 :func:`abi_kit.decode_event_log` 口径一致。
- 可选 ``event`` 为规范签名（``Transfer(address,address,uint256)``）或
  唯一事件名；缺省时非匿名事件按 topics 首项匹配注册表 topic0，匿名
  事件必须显式选择。显式事件与 topics[0] 的 topic0 不一致时不得解码。
- values 语义同 :func:`abi_kit.decode_event_log`：非 indexed 参数由
  data 严格 ABI 解码；indexed 的 string、动态 bytes、数组与 tuple 不可
  逆，values 中对应位置为 32 字节 topic bytes。

错误约定：

- 注册表构建与分派失败统一抛 :class:`abi_kit.AbiLogDispatchError`，以
  ``code`` 区分（LOG_ABI_INVALID / LOG_ENTRY_INVALID /
  LOG_EVENT_NOT_FOUND / LOG_EVENT_AMBIGUOUS / LOG_EVENT_REQUIRED /
  LOG_TOPIC_MISMATCH）。
- 分派成功后的单条日志还原委托 :func:`abi_kit.decode_event_log`，其
  :class:`abi_kit.AbiEventError` 与错误码原样传播，保持不变。
"""

from __future__ import annotations

import json
from collections.abc import Mapping
from dataclasses import dataclass, field

from ._event import (
    EventDefinition,
    _data_bytes,
    _event_signature,
    _topic_bytes,
    decode_event_log,
    event_topic0,
    parse_event_abi,
)
from ._exceptions import AbiEventError, AbiLogDispatchError


# ---- 不可变注册表 ----------------------------------------------------------


@dataclass(frozen=True)
class EventRegistry:
    """不可变合约事件注册表（按 ABI 声明顺序保存事件）。

    - ``events``：按 ABI 顺序保存的 :class:`EventDefinition` tuple。

    规范签名唯一的约束由 :func:`parse_event_registry` 校验；直接构造不
    做该项检查。名称、规范签名与 topic0 的查找索引在构造时预计算。
    """

    events: tuple[EventDefinition, ...] = field(default=())
    _by_signature: dict = field(init=False, repr=False, compare=False)
    _by_name: dict = field(init=False, repr=False, compare=False)
    _by_topic0: dict = field(init=False, repr=False, compare=False)

    def __post_init__(self):
        by_signature: dict = {}
        by_name: dict = {}
        by_topic0: dict = {}
        for event in self.events:
            by_signature.setdefault(_event_signature(event), event)
            by_name.setdefault(event.name, []).append(event)
            if not event.anonymous:
                topic0 = event_topic0(event)
                by_topic0.setdefault(bytes.fromhex(topic0[2:]), event)
        object.__setattr__(self, "_by_signature", by_signature)
        object.__setattr__(self, "_by_name", by_name)
        object.__setattr__(self, "_by_topic0", by_topic0)

    def __len__(self) -> int:
        return len(self.events)


# ---- 注册表解析 ------------------------------------------------------------


def _abi_invalid(message: str) -> AbiLogDispatchError:
    return AbiLogDispatchError("LOG_ABI_INVALID", message)


def parse_event_registry(abi) -> EventRegistry:
    """解析 ABI，按声明顺序构建不可变 :class:`EventRegistry`。

    ``abi`` 接受 ABI JSON 字符串（:func:`json.loads` 口径）或等价的
    Python 条目数组（list/tuple）。只保留 ``type == "event"`` 的条目，
    其余条目（function/constructor/error/receive/fallback、缺 type、
    未知类型或非对象条目）跳过不解析。事件条目的 name、inputs、
    indexed、anonymous 与 tuple components 语义同
    :func:`abi_kit.parse_event_abi`；事件的规范签名
    （``Name(type1,type2,...)``，anonymous 不参与）不得重复。

    ABI 根非法、event 条目非法或规范签名重复时抛
    :class:`abi_kit.AbiLogDispatchError`（code 为 ``LOG_ABI_INVALID``）。
    """
    if isinstance(abi, str):
        try:
            root = json.loads(abi)
        except (json.JSONDecodeError, ValueError) as exc:
            raise _abi_invalid(f"ABI JSON 解析失败：{exc}") from None
    elif isinstance(abi, (list, tuple)):
        root = abi
    else:
        raise _abi_invalid(
            f"ABI 必须是 JSON 字符串或条目数组，得到 {type(abi).__name__}"
        )

    if not isinstance(root, (list, tuple)):
        raise _abi_invalid("ABI 必须是条目数组，JSON 根不能是对象或标量")

    events: list[EventDefinition] = []
    signatures: set[str] = set()
    for entry in root:
        if not isinstance(entry, dict) or entry.get("type") != "event":
            # 非 event 条目（含缺 type、未知类型、非对象）跳过不解析。
            continue
        try:
            event = parse_event_abi(entry)
        except AbiEventError as exc:
            raise _abi_invalid(f"event 条目非法：{exc}") from None
        signature = _event_signature(event)
        if signature in signatures:
            raise _abi_invalid(f"事件规范签名重复：{signature}")
        signatures.add(signature)
        events.append(event)
    return EventRegistry(tuple(events))


# ---- 日志字段规范化 --------------------------------------------------------


def _entry_invalid(message: str) -> AbiLogDispatchError:
    return AbiLogDispatchError("LOG_ENTRY_INVALID", message)


def _normalize_topics(topics) -> tuple[bytes, ...]:
    """把日志 topics 规范化为 32 字节 bytes tuple，失败抛 LOG_ENTRY_INVALID。"""
    if isinstance(topics, (str, bytes)) or not isinstance(topics, (list, tuple)):
        raise _entry_invalid(
            f"topics 必须是列表或元组，得到 {type(topics).__name__}"
        )
    normalized: list[bytes] = []
    for item in topics:
        try:
            normalized.append(_topic_bytes(item))
        except AbiEventError as exc:
            raise _entry_invalid(f"topics 项非法：{exc}") from None
    return tuple(normalized)


def _normalize_data(data) -> bytes:
    """把日志 data 规范化为 bytes，失败抛 LOG_ENTRY_INVALID。"""
    try:
        return _data_bytes(data)
    except AbiEventError as exc:
        raise _entry_invalid(f"data 非法：{exc}") from None


# ---- 事件分派 --------------------------------------------------------------


def _require_registry(registry) -> EventRegistry:
    if not isinstance(registry, EventRegistry):
        raise _abi_invalid(
            f"需要 EventRegistry，得到 {type(registry).__name__}"
        )
    return registry


def _resolve_event(registry: EventRegistry, selector) -> EventDefinition:
    """按规范签名或唯一事件名在注册表中定位事件。"""
    if not isinstance(selector, str) or not selector:
        raise _entry_invalid(f"event 字段必须是非空字符串，得到 {selector!r}")

    if "(" in selector or ")" in selector:
        event = registry._by_signature.get(selector)
        if event is None:
            raise AbiLogDispatchError(
                "LOG_EVENT_NOT_FOUND",
                f"注册表中找不到规范签名为 {selector!r} 的事件",
            )
        return event

    candidates = registry._by_name.get(selector, [])
    if not candidates:
        raise AbiLogDispatchError(
            "LOG_EVENT_NOT_FOUND", f"注册表中找不到事件 {selector!r}"
        )
    if len(candidates) > 1:
        signatures = ", ".join(_event_signature(event) for event in candidates)
        raise AbiLogDispatchError(
            "LOG_EVENT_AMBIGUOUS",
            f"事件 {selector!r} 存在 {len(candidates)} 个同名事件，无法唯一"
            f"选择，请改用规范签名之一：{signatures}",
        )
    return candidates[0]


def _dispatch_by_topic0(registry: EventRegistry, topics: tuple[bytes, ...]):
    """无显式事件时按 topics 首项的 topic0 分派非匿名事件。"""
    if not topics:
        # 只有匿名事件（且无 indexed 参数）才可能产生空 topics 的日志。
        if any(event.anonymous for event in registry.events):
            raise AbiLogDispatchError(
                "LOG_EVENT_REQUIRED",
                "topics 为空且未显式指定 event：匿名事件必须显式选择",
            )
        raise AbiLogDispatchError(
            "LOG_EVENT_NOT_FOUND",
            "topics 为空，无法匹配任何非匿名事件的 topic0",
        )
    event = registry._by_topic0.get(topics[0])
    if event is None:
        raise AbiLogDispatchError(
            "LOG_EVENT_NOT_FOUND",
            f"topic0 0x{topics[0].hex()} 未匹配注册表中的任何事件",
        )
    return event


def _dispatch(registry: EventRegistry, log):
    """校验日志映射并分派事件，返回 (event, topics, data)。"""
    if not isinstance(log, Mapping):
        raise _entry_invalid(f"日志必须是映射，得到 {type(log).__name__}")
    if "topics" not in log:
        raise _entry_invalid("日志缺少必填字段 topics")
    if "data" not in log:
        raise _entry_invalid("日志缺少必填字段 data")

    topics = _normalize_topics(log["topics"])
    data = _normalize_data(log["data"])

    selector = log.get("event")
    if selector is None:
        event = _dispatch_by_topic0(registry, topics)
    else:
        event = _resolve_event(registry, selector)
        if not event.anonymous:
            expected_topic0 = bytes.fromhex(event_topic0(event)[2:])
            if not topics or topics[0] != expected_topic0:
                raise AbiLogDispatchError(
                    "LOG_TOPIC_MISMATCH",
                    f"显式事件 {_event_signature(event)} 与 topics[0] 的 "
                    "topic0 不一致",
                )
    return event, topics, data


# ---- 日志还原 --------------------------------------------------------------


def decode_contract_event_log(registry, log) -> tuple:
    """分派并还原单条合约事件日志。

    ``registry`` 为 :func:`parse_event_registry` 构建的
    :class:`EventRegistry`；``log`` 为映射，``topics`` 与 ``data`` 必填，
    可选 ``event`` 指定规范签名或唯一事件名。

    返回 ``(event, topics, data, values)`` 四元组：命中的
    :class:`EventDefinition`、规范化的 32 字节 topics bytes tuple、data
    bytes 与按声明顺序排列的 values tuple（口径同
    :func:`abi_kit.decode_event_log`）。

    分派失败抛 :class:`abi_kit.AbiLogDispatchError`；分派成功后的日志
    还原失败抛 :class:`abi_kit.AbiEventError`（错误码不变）。
    """
    _require_registry(registry)
    event, topics, data = _dispatch(registry, log)
    values = decode_event_log(event, topics, data)
    return (event, topics, data, values)


def decode_contract_event_logs(registry, logs) -> tuple:
    """按输入顺序批量分派并还原日志序列。

    ``logs`` 为日志映射组成的 list/tuple；返回与输入等长、顺序一致的
    四元组 tuple，每项口径同 :func:`decode_contract_event_log`。任一
    日志失败即整体抛出，不返回部分结果。
    """
    _require_registry(registry)
    if isinstance(logs, (str, bytes)) or not isinstance(logs, (list, tuple)):
        raise _entry_invalid(
            f"日志序列必须是 list 或 tuple，得到 {type(logs).__name__}"
        )
    return tuple(decode_contract_event_log(registry, log) for log in logs)

