                "type": "event",
                "name": "M",
                "inputs": [{"indexed": True, "name": "v", "type": "bytes4"}],
            }
        )
        result = encode_event_log(event, [b"abcd"])
        self.assertEqual(result.topics[1], b"abcd" + b"\x00" * 28)


class EncodeDecodeRoundTripTests(unittest.TestCase):
