            self._code(self.event, topics, self.encoded.data,
                       [ADDR_A, ADDR_B, 1000]),
            "EVENT_TOPIC_VALUE",
        )

    def test_no_value_layer_exceptions_leak(self):
        from abi_kit import ABIValueError, ABITypeError

